  color: #ffffff;
  padding: 2px 6px;
  border-radius: 9999px;
  display: inline-block;
}
.ds-chip-thumbprint {
  font-family: -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 12px;
  font-weight: 500;
  padding: 5px 12px;
  border-radius: 9999px;
  border: 1px solid var(--border-color, #d1d5db);
  background: var(--bg-surface, #ffffff);
  color: var(--fg-default);
  cursor: pointer;
  transition: all 0.15s ease;
}
.ds-chip-thumbprint.active {
  background: #009fd9;
  border-color: #009fd9;
  color: #ffffff;
}
.ds-chip-thumbprint:focus-visible { box-shadow: 0 0 0 2px #009fd9; outline: none; }
.ds-tag-thumbprint {
  font-family: -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 12px;
  padding: 4px 10px;
  background: var(--bg-subtle, #f3f4f6);
  border: 1px solid var(--border-color, #e5e7eb);
  border-radius: 4px;
  color: var(--fg-default);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.ds-tag-remove-thumbprint {
  background: transparent;
  border: none;
  cursor: pointer;
  font-size: 12px;
  padding: 0;
  color: var(--fg-muted);
}
.ds-tag-remove-thumbprint:hover { color: #dc2626; }

/* Accordion */
.ds-accordion-thumbprint {
  border-radius: 4px;
  border: 1px solid var(--border-color, #e5e7eb);
  overflow: hidden;
}
.ds-accordion-item-thumbprint {
  border-bottom: 1px solid var(--border-color, #e5e7eb);
}
.ds-accordion-item-thumbprint:last-child {
  border-bottom: none;
}
.ds-accordion-trigger-thumbprint {
  font-family: -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 14px;
  font-weight: 600;
  width: 100%;
  padding: 14px 16px;
  background: transparent;
  border: none;
  cursor: pointer;
