  background: var(--bg-subtle, #f9fafb);
}
.ds-accordion-trigger-thumbprint:focus-visible {
  box-shadow: 0 0 0 2px #009fd9;
  outline: none;
}
.ds-accordion-chevron-thumbprint {
  font-size: 12px;
  transition: transform 0.2s ease;
  display: inline-block;
}
.ds-accordion-chevron-thumbprint.rotated {
  transform: rotate(180deg);
}
.ds-accordion-panel-thumbprint {
  font-family: -apple-system, BlinkMacSystemFont, sans-serif;
  padding: 0 16px 14px;
  color: var(--fg-muted);
