}
.ds-tr-c64-css.selected {
  background: var(--accent-subtle, rgba(37,99,235,0.06));
}

/* Alert */
.ds-alert-c64-css {
  font-family: 'Courier New', monospace;
  border-radius: 0px;
  padding: 12px 16px;
